package com.turboio.addon;
import java.util.*;
import android.os.SystemClock;
final class NativeTransfer{interface Receiver{void message(String peer,byte[] bytes);}static Receiver receiver;static String peer="test-peer",lease="";static final List<byte[]> packets=new ArrayList<>();static Runnable fail;static final Main MAIN=new Main();static final class Main{static final class Delayed{final Runnable task;final long due;Delayed(Runnable t,long d){task=t;due=d;}}final List<Runnable> ready=new ArrayList<>();final List<Delayed> delayed=new ArrayList<>();void post(Runnable r){ready.add(r);}void postDelayed(Runnable r,long n){removeCallbacks(r);delayed.add(new Delayed(r,SystemClock.now+n));}void removeCallbacks(Runnable r){ready.removeIf(x->x==r);delayed.removeIf(x->x.task==r);}void drain(){while(!ready.isEmpty())ready.remove(0).run();}void advance(long n){SystemClock.now+=n;for(;;){int at=-1;long due=Long.MAX_VALUE;for(int i=0;i<delayed.size();i++)if(delayed.get(i).due<=SystemClock.now&&delayed.get(i).due<due){at=i;due=delayed.get(i).due;}if(at<0)break;delayed.remove(at).task.run();drain();}}}static void receive(Receiver r){receiver=r;}static String connected(){return peer;}static boolean acquireMessages(String who){if(!lease.isEmpty())return false;lease=who;return true;}static void releaseMessages(String who){if(lease.equals(who))lease="";}static void sendMessage(String who,String device,byte[] bytes,Runnable failed){if(!lease.equals(who)||!peer.equals(device))throw new IllegalStateException();packets.add(bytes.clone());fail=failed;}}
